<template><section class="workbench"><nav class="categories"><h2>内容类型</h2><button v-for="c in workshopCategories" :key="c" :class="{active:category===c}" @click="selectCategory(c)"><span>{{c}}</span><small>{{Object.keys(registry(c)).length}}</small></button></nav><section class="catalog"><header><h2>{{category}}</h2><button class="primary" @click="createAsset">+ 新建</button></header><label>搜索名称或说明<input v-model="queries[category]" type="search"></label><p aria-live="polite">{{filtered.length}} 项结果</p><div v-if="!Object.keys(registry(category)).length" class="empty"><b>还没有{{category}}</b><button @click="createAsset">新建{{category}}</button></div><div v-else-if="!filtered.length" class="empty"><b>没有匹配结果</b><button @click="queries[category]=''">清除搜索</button></div><div class="asset-list"><button v-for="item in filtered" :key="item.id" :class="{active:selectedId===item.id}" @click="selectedId=item.id"><strong>{{item.title}}</strong><span>{{item.summary||'暂无摘要'}}</span><small v-if="isDirty(item.id)">● 未保存</small></button></div></section><main class="editing"><header v-if="entry"><div><small>{{category}}</small><h2>{{assetTitle(category,entry)}}</h2></div><div><button @click="copyAsset">复制</button><button @click="exportOpen=true">导出</button><button class="danger" @click="askDelete">删除</button></div></header><DomainAssetEditor v-if="entry" :category="category" :entry="entry" :source="draft" @request-role-type="askRoleType"/><div v-else class="empty"><b>选择或新建一项{{category}}</b></div></main><aside class="status"><h2>工作状态</h2><div class="state" :class="{ok:!changes.length}"><b>{{changes.length ? `${changes.length} 项资产未保存` : '所有更改已保存'}}</b><span>{{issues.length ? `${issues.length} 处引用需修复` : '引用检查通过'}}</span></div><h3>发布检查</h3><button v-for="issue in issues" :key="issue.ownerCategory+issue.ownerId+issue.field" class="issue" @click="locate(issue.ownerCategory,issue.ownerId)">{{assetTitle(issue.ownerCategory,registry(issue.ownerCategory)[issue.ownerId])}}<span>{{issue.field}} 缺少{{issue.targetCategory}}</span></button><p v-if="!issues.length" class="pass">✓ 未发现缺失引用</p></aside><footer class="savebar"><span>{{changes.length}} 项未保存</span><div><button :disabled="!changes.length" @click="$emit('requestReload')">放弃草稿</button><button class="primary" :disabled="!changes.length" @click="reviewOpen=true">审阅并保存</button></div></footer>
<AppDialog :open="reviewOpen" title="审阅本次保存" @cancel="reviewOpen=false"><details v-for="change in changes" :key="change.category+change.id" open><summary>{{kindLabel[change.kind]}} · {{change.category}} · {{change.title}}</summary><dl><template v-for="field in change.fields" :key="field.path"><dt>{{field.path}}</dt><dd>{{format(field.oldValue)}} → {{format(field.newValue)}}</dd></template></dl></details><template #actions><button class="primary" @click="reviewOpen=false;$emit('save')">确认保存</button></template></AppDialog><AppDialog :open="!!deleting" title="删除资产" @cancel="deleting=undefined"><p v-if="deleting?.length">该资产被 {{deleting.length}} 处引用。删除将清理引用并使相关剧本不可用。</p><p v-else>该资产没有被引用。</p><button v-for="x in deleting" :key="x.ownerCategory+x.ownerId+x.field" class="issue" @click="deleting=undefined;locate(x.ownerCategory,x.ownerId)">{{x.ownerCategory}} · {{assetTitle(x.ownerCategory,registry(x.ownerCategory)[x.ownerId])}} · {{x.field}}</button><template #actions><button class="danger" @click="confirmDelete">删除{{deleting?.length?`并清理 ${deleting.length} 处引用`:''}}</button></template></AppDialog><AppDialog :open="exportOpen" title="导出预览" @cancel="exportOpen=false"><p>将导出 1 项：{{category}} · {{entry&&assetTitle(category,entry)}}。</p><p v-if="issues.length">当前工作区有 {{issues.length}} 处缺失引用。</p><template #actions><button class="primary" @click="confirmExport">下载资产包</button></template></AppDialog><AppDialog :open="!!pendingRoleType" title="转换角色类型" @cancel="pendingRoleType=''" ><p>将移除不适用字段：{{removedRoleFields.join('、')||'无'}}；共用字段保留。</p><template #actions><button class="danger" @click="confirmRoleType">确认转换</button></template></AppDialog></section></template>
<script setup lang="ts">/* eslint-disable vue/no-mutating-props */import{klona}from'klona';import{computed,reactive,ref}from'vue';import{deleteAsset,findReferenceIssues,findReferencesTo,type WorkshopCategory}from'../assets/model';import{createPackage,downloadPackage}from'../assets/package';import{assetSummary,assetTitle,createDefaultAsset,defaultRoleData,diffSources,workshopCategories}from'../assets/presentation';import type{ReferenceIssue,ScenarioSourceBundle}from'../scenario/types';import AppDialog from'./AppDialog.vue';import DomainAssetEditor from'./DomainAssetEditor.vue';const props=defineProps<{source:ScenarioSourceBundle;draft:ScenarioSourceBundle}>();defineEmits<{save:[];requestReload:[]}>();const category=ref<WorkshopCategory>('开场白'),selectedId=ref(''),queries=reactive(Object.fromEntries(workshopCategories.map(c=>[c,'']))as Record<WorkshopCategory,string>),reviewOpen=ref(false),exportOpen=ref(false),pendingRoleType=ref(''),deleting=ref<ReferenceIssue[]|undefined>();function registry(c:WorkshopCategory):Record<string,any>{return c==='开场白'?props.draft.scenarios:props.draft.registries[c]}const entry=computed<any>(()=>registry(category.value)[selectedId.value]);const changes=computed(()=>diffSources(props.source,props.draft)),issues=computed(()=>findReferenceIssues(props.draft));const filtered=computed(()=>Object.entries(registry(category.value)).map(([id,v])=>({id,title:assetTitle(category.value,v),summary:assetSummary(category.value,v)})).filter(x=>`${x.title} ${x.summary}`.toLowerCase().includes(queries[category.value].toLowerCase())));const kindLabel={added:'新增',removed:'删除',modified:'修改'};const removedRoleFields=computed(()=>entry.value&&pendingRoleType.value?Object.keys(entry.value.data).filter(k=>!(k in defaultRoleData(pendingRoleType.value))):[]);function selectCategory(c:WorkshopCategory){category.value=c;selectedId.value=''}function createAsset(){const id=crypto.randomUUID();registry(category.value)[id]=createDefaultAsset(category.value);selectedId.value=id}function copyAsset(){const id=crypto.randomUUID(),v=klona(entry.value);if('key'in v)v.key=`${v.key||assetTitle(category.value,v)}副本`;registry(category.value)[id]=v;selectedId.value=id}function isDirty(id:string){return changes.value.some(x=>x.category===category.value&&x.id===id)}function locate(c:WorkshopCategory,id:string){category.value=c;selectedId.value=id}function askDelete(){deleting.value=category.value==='开场白'?[]:findReferencesTo(props.draft,category.value,selectedId.value)}function confirmDelete(){if(category.value==='开场白')delete props.draft.scenarios[selectedId.value];else deleteAsset(props.draft,category.value,selectedId.value,true);selectedId.value='';deleting.value=undefined}function confirmExport(){downloadPackage(createPackage(props.draft,{[category.value]:[selectedId.value]}),assetTitle(category.value,entry.value));exportOpen.value=false}function askRoleType(v:string){pendingRoleType.value=v}function confirmRoleType(){const next=defaultRoleData(pendingRoleType.value);for(const k of Object.keys(next))if(k in entry.value.data)next[k]=klona(entry.value.data[k]);entry.value.data=next;entry.value.type=pendingRoleType.value;pendingRoleType.value=''}function format(v:unknown){if(v===undefined)return'未设置';const s=typeof v==='string'?v:JSON.stringify(v);return s.length>90?s.slice(0,90)+'…':s}</script>
<style scoped>.workbench{display:grid;grid-template-columns:184px 288px minmax(420px,1fr) 280px;gap:1px;min-height:calc(100vh - 140px);margin-top:16px;background:#393d3f}.categories,.catalog,.editing,.status{min-width:0;padding:16px;background:#15181a}.categories,.asset-list{display:flex;flex-direction:column}.categories button,.catalog header,.editing>header,.savebar,.savebar div{display:flex;justify-content:space-between;gap:8px}.categories button.active,.asset-list button.active{outline:2px solid #cbb477}.catalog label{display:grid;gap:5px}.asset-list{gap:6px;max-height:65vh;overflow:auto}.asset-list button,.issue{text-align:left}.asset-list strong,.asset-list span,.asset-list small,.issue span{display:block}.asset-list span,.status span{color:#b8b09f}.asset-list small{color:#d8a95d}.editing{max-height:calc(100vh - 140px);overflow:auto}.editing>header{position:sticky;top:-16px;z-index:2;margin:-16px -16px 12px;padding:16px;background:#15181a}.state{display:grid;gap:5px;padding:12px;border-left:3px solid #d8a95d;background:#30261d}.state.ok{border-color:#72b58a;background:#18291f}.issue{width:100%}.pass{color:#72b58a}.savebar{position:fixed;z-index:20;right:0;bottom:0;left:0;padding:12px 22px;background:#0d0f10;border-top:1px solid #4c4f50}.empty{display:grid;gap:12px;padding:30px;text-align:center}.danger{color:#f1c2bc!important;border-color:#d47569!important}details{padding:10px;background:#15181a}dl{display:grid;grid-template-columns:1fr 2fr;gap:6px}dd{margin:0;overflow-wrap:anywhere}@media(max-width:1100px){.workbench{grid-template-columns:160px 250px 1fr}.status{display:none}}@media(max-width:700px){.workbench{display:block}.categories{flex-direction:row;overflow:auto;padding:8px}.categories h2{display:none}.categories button{flex:none}.editing{max-height:none}.savebar{padding:8px}}</style>
